js = r'''
const LIVE_SHOOT_ADDON={id:'live-shoot-pro',name:'Live Shoot Pro',priceLabel:'Paid add-on'};
function liveShootPreviewMode(){try{return new URLSearchParams(location.search).get('live-shoot-preview')==='1'}catch{return false}}
function liveShootEntitled(){return D.settings.liveShootProActive===true||liveShootPreviewMode()}
function liveState(s){if(!s.liveShoot||typeof s.liveShoot!=='object')s.liveShoot={status:'not_started',startedAt:null,endedAt:null,currentShotId:null,items:{}};const st=s.liveShoot;st.items=st.items&&typeof st.items==='object'?st.items:{};for(const shot of s.shots){if(!st.items[shot.id])st.items[shot.id]={state:'pending',captures:0,note:'',updatedAt:null}}if(!st.currentShotId||!s.shots.some(x=>x.id===st.currentShotId))st.currentShotId=s.shots.find(x=>!x.skip)?.id||s.shots[0]?.id||null;return st}
function liveItem(s,id){const st=liveState(s);if(!st.items[id])st.items[id]={state:'pending',captures:0,note:'',updatedAt:null};return st.items[id]}
function liveSummary(s){const rows=s.shots.filter(x=>!x.skip),out={total:rows.length,done:0,pending:0,reshoot:0,skipped:0,captures:0,percent:0,ready:false};for(const shot of rows){const it=liveItem(s,shot.id);out.captures+=Number(it.captures)||0;if(it.state==='done')out.done++;else if(it.state==='reshoot')out.reshoot++;else if(it.state==='skipped')out.skipped++;else out.pending++}out.percent=out.total?Math.round(out.done/out.total*100):0;out.ready=out.total>0&&out.done===out.total;return out}
function liveStateText(state){return state==='done'?'Covered':state==='reshoot'?'Needs another':state==='skipped'?'Skipped':'Not shot'}
function liveStateClass(state){return state==='done'?'done':state==='reshoot'?'reshoot':state==='skipped'?'skipped':''}
function liveNextUnresolvedId(s,afterId){const rows=s.shots.filter(x=>!x.skip),idx=Math.max(0,rows.findIndex(x=>x.id===afterId));for(let off=1;off<=rows.length;off++){const shot=rows[(idx+off)%rows.length],it=liveItem(s,shot.id);if(it.state!=='done'&&it.state!=='skipped')return shot.id}return rows[(idx+1)%Math.max(1,rows.length)]?.id||afterId}
function startLiveShoot(s){const st=liveState(s),first=!st.startedAt;st.status='live';st.startedAt=st.startedAt||Date.now();st.endedAt=null;if(first)activity(s,'Live Shoot started',`${s.shots.filter(x=>!x.skip).length} requirements`);save();renderWorkspace();toast('Live Shoot started')}
function resumeLiveShoot(s){const st=liveState(s);st.status='live';st.endedAt=null;activity(s,'Live Shoot resumed');save();renderWorkspace()}
function liveSetCurrent(s,id){const st=liveState(s);if(!s.shots.some(x=>x.id===id))return;st.currentShotId=id;if(st.status==='not_started')st.status='live';save();renderWorkspace()}
function liveBumpCapture(s,id){const st=liveState(s),it=liveItem(s,id);it.captures=(Number(it.captures)||0)+1;it.state='done';it.updatedAt=Date.now();st.status='live';save();renderWorkspace();toast(`${it.captures} capture${it.captures===1?'':'s'} logged`)}
function liveMark(s,id,state){const st=liveState(s),it=liveItem(s,id);it.state=state;it.updatedAt=Date.now();st.status='live';if(state==='done'&&Number(it.captures)===0)it.captures=1;if(state==='done'||state==='skipped'){const next=liveNextUnresolvedId(s,id);if(next)st.currentShotId=next}save();renderWorkspace()}
function liveMove(s,dir){const st=liveState(s),rows=s.shots.filter(x=>!x.skip);if(!rows.length)return;let i=rows.findIndex(x=>x.id===st.currentShotId);if(i<0)i=0;i=(i+dir+rows.length)%rows.length;st.currentShotId=rows[i].id;save();renderWorkspace()}
function liveNoteModal(s,id){const shot=s.shots.find(x=>x.id===id);if(!shot)return;const it=liveItem(s,id);showModal(`<h3>Live note — ${esc(shot.subject)}</h3><p>${esc(shot.variant)} · keep a quick on-location note with this requirement.</p><div class="field"><textarea id="liveNoteText" style="min-height:130px" placeholder="Client wants another angle, garnish moved, reshoot after mains…">${esc(it.note||'')}</textarea></div><div class="actions section" style="justify-content:flex-end"><button class="btn secondary" data-close>Cancel</button><button class="btn primary" id="saveLiveNote">${icon('save')}Save Note</button></div>`);document.getElementById('saveLiveNote').onclick=()=>{it.note=document.getElementById('liveNoteText').value.trim();it.updatedAt=Date.now();save();closeModal();renderWorkspace();toast('Live note saved')}}
function finishLiveShoot(s,force=false){const sum=liveSummary(s);if(!sum.ready&&!force)return liveShootCheck(s);const st=liveState(s);st.status='complete';st.endedAt=Date.now();activity(s,'Live Shoot completed',`${sum.done}/${sum.total} requirements covered${sum.reshoot?` · ${sum.reshoot} need another`:''}${sum.pending?` · ${sum.pending} missing`:''}`);save();closeModal();renderWorkspace();toast(sum.ready?'Live Shoot complete — all required shots covered':'Live Shoot ended with outstanding shots')}
function liveShootCheck(s){const sum=liveSummary(s),missing=[],reshoot=[],skipped=[];for(const shot of s.shots.filter(x=>!x.skip)){const it=liveItem(s,shot.id);if(it.state==='pending')missing.push(shot);if(it.state==='reshoot')reshoot.push(shot);if(it.state==='skipped')skipped.push(shot)}const rows=(arr,label)=>arr.length?`<div class="section"><strong>${label}</strong><div class="shot-note" style="margin-top:7px">${arr.map(x=>`${esc(x.subject)} — ${esc(x.variant)}`).join('<br>')}</div></div>`:'';showModal(`<h3>${sum.ready?'Shoot coverage complete':'Check before you leave'}</h3><p>${sum.ready?'Every required shot has been marked covered.':'High Style Match found requirements that still need your attention.'}</p><div class="live-check-grid"><div class="live-check-stat"><b>${sum.done}</b><span>Covered</span></div><div class="live-check-stat"><b>${sum.pending}</b><span>Missing</span></div><div class="live-check-stat"><b>${sum.reshoot}</b><span>Needs another</span></div><div class="live-check-stat"><b>${sum.skipped}</b><span>Skipped</span></div></div>${rows(missing,'Still missing')}${rows(reshoot,'Needs another frame')}${rows(skipped,'Skipped on location')}<div class="actions section" style="justify-content:flex-end"><button class="btn secondary" data-close>Keep Shooting</button>${sum.ready?`<button class="btn primary" id="finishLive">${icon('check')}Finish Live Shoot</button>`:`<button class="btn secondary" id="finishLiveAnyway">Finish Anyway</button>`}</div>`);const a=document.getElementById('finishLive');if(a)a.onclick=()=>finishLiveShoot(s,true);const b=document.getElementById('finishLiveAnyway');if(b)b.onclick=()=>finishLiveShoot(s,true)}
async function liveFullscreen(){const el=document.getElementById('workspaceBody');try{if(document.fullscreenElement){await document.exitFullscreen();return}if(el?.requestFullscreen){await el.requestFullscreen();return}toast('Full-screen mode is not supported by this browser. Live Shoot is still touch-optimised.')}catch{toast('This browser could not enter full-screen mode.')}}
function showLiveShootUpgrade(){showModal(`<div class="live-pro-kicker">Optional premium feature</div><h3 style="margin-top:7px">Upgrade to Live Shoot Pro</h3><p>Live Shoot Pro is a paid add-on for photographers who want to track the brief while they are on location.</p><div class="notice info section">${icon('info')}Customer billing and account entitlements will activate this feature. The public web build does not store payment credentials or a secret unlock key.</div><div class="section shot-note"><strong>Includes:</strong><br>Touch-first shot tracking · capture counts · reshoot flags · live notes · shoot queue · before-you-leave coverage check · session history.</div><div class="actions section" style="justify-content:flex-end"><button class="btn primary" data-close>Got it</button></div>`)}
function appendLiveShootOverview(s){const W=document.getElementById('workspaceBody');if(!W)return;const active=liveShootEntitled(),sum=s.shots.length?liveSummary(s):null,card=document.createElement('div');card.className='live-pro-card';card.innerHTML=`<div><div class="live-pro-kicker">Optional add-on</div><h3>Live Shoot Pro ${active?'<span class="live-pro-tag active" style="margin-left:7px">Active</span>':'<span class="live-pro-tag" style="margin-left:7px">Paid add-on</span>'}</h3><p>${active&&sum?`${sum.done}/${sum.total} requirements covered in the live session. `:''}Run the client shot list on an iPad or laptop while you shoot, flag reshoots and check coverage before leaving the location.</p></div><button class="btn ${active?'primary':'secondary'}" id="overviewLivePro">${icon(active?'arrow':'star')}${active?'Open Live Shoot':'View Live Shoot Pro'}</button>`;W.appendChild(card);document.getElementById('overviewLivePro').onclick=()=>{tab='live';renderWorkspace()}}
function appendLiveShootSettings(){const grid=document.querySelector('.settings-grid');if(!grid)return;const active=liveShootEntitled(),card=document.createElement('div');card.className='setting-card live-settings-card';card.innerHTML=`<h2>Live Shoot Pro <span class="live-pro-tag ${active?'active':''}">${active?'Active':'Paid add-on'}</span></h2><p>Optional on-location coverage tracking for photographers. It does not change the standard High Style Match workflow for customers who do not buy the add-on.</p><button class="btn ${active?'primary':'secondary'}" id="settingsLivePro">${icon(active?'check':'star')}${active?'Live Shoot Pro active':'Upgrade Live Shoot Pro'}</button>${liveShootPreviewMode()?'<div class="shot-note section">Owner preview mode is active on this browser session.</div>':''}`;grid.insertBefore(card,grid.firstChild);document.getElementById('settingsLivePro').onclick=()=>active?toast('Live Shoot Pro is active on this account'):showLiveShootUpgrade()}
function renderLiveShootTab(W,s,c){if(!s.shots.length){W.innerHTML=`<div class="empty"><div class="empty-icon">${icon('upload')}</div><h3>Add the shot list first</h3><p>Live Shoot Pro runs directly from the client brief, so the project needs shot-list requirements before you can start.</p><button class="btn primary" id="liveGoShotList">${icon('upload')}Open Shot List</button></div>`;document.getElementById('liveGoShotList').onclick=()=>{tab='shotlist';renderWorkspace()};return}if(!liveShootEntitled()){W.innerHTML=`<div class="live-paywall"><span class="live-pro-tag">Paid add-on</span><h2>Live Shoot Pro</h2><p>Turn the shot list into a touch-first on-location assistant. Track every required frame as you shoot and check the whole brief before you leave.</p><div class="live-feature-grid"><div class="live-feature"><strong>Live coverage</strong><span>See exactly what is covered, missing or needs another frame.</span></div><div class="live-feature"><strong>Touch-first queue</strong><span>Keep Now, Next and the remaining requirements visible on an iPad or laptop.</span></div><div class="live-feature"><strong>Before-you-leave check</strong><span>Catch forgotten requirements while you can still photograph them.</span></div></div><button class="btn primary" id="upgradeLivePro">${icon('star')}Upgrade Live Shoot Pro</button></div>`;document.getElementById('upgradeLivePro').onclick=showLiveShootUpgrade;return}const st=liveState(s),sum=liveSummary(s);if(st.status==='not_started'){W.innerHTML=`<div class="live-launch"><div class="live-launch-main"><div><span class="live-pro-tag active">${liveShootPreviewMode()?'Owner preview':'Live Shoot Pro'}</span><h2>Run the brief while you shoot.</h2><p>Keep this screen open on an iPad or laptop. Tap each requirement as it is captured, log extra frames, flag reshoots and run a final coverage check before leaving the venue.</p></div><div class="actions"><button class="btn primary" id="startLiveShoot">${icon('spark')}Start Live Shoot</button><button class="btn secondary" id="liveFullscreenLaunch">Full Screen</button></div></div><div class="live-launch-side"><div class="live-launch-stat"><label>Required shots</label><b>${sum.total}</b></div><div class="live-launch-stat"><label>Already covered</label><b>${sum.done}</b></div><div class="live-launch-stat"><label>Live captures logged</label><b>${sum.captures}</b></div></div></div>`;document.getElementById('startLiveShoot').onclick=()=>startLiveShoot(s);document.getElementById('liveFullscreenLaunch').onclick=liveFullscreen;return}const rows=s.shots.filter(x=>!x.skip),current=rows.find(x=>x.id===st.currentShotId)||rows[0],it=current?liveItem(s,current.id):null,idx=current?rows.findIndex(x=>x.id===current.id):-1,next=idx>=0?rows[(idx+1)%rows.length]:null;W.innerHTML=`<div class="live-shell">${st.status==='complete'?`<div class="notice success">${icon('check')}Live Shoot ended ${st.endedAt?new Date(st.endedAt).toLocaleString():''}. Resume it if you need another frame.</div>`:''}<div class="live-top"><div><div class="live-pro-kicker" style="color:#b8a7ff">Live Shoot Pro</div><h2>${esc(s.client)} · ${esc(s.name)}</h2><p>${sum.done} of ${sum.total} required shots covered · ${sum.captures} captures logged</p><div class="live-meter"><i style="width:${sum.percent}%"></i></div></div><div class="live-top-stats"><div class="live-top-stat"><b>${sum.percent}%</b><span>Covered</span></div><div class="live-top-stat"><b>${sum.pending}</b><span>Missing</span></div><div class="live-top-stat"><b>${sum.reshoot}</b><span>Reshoot</span></div></div></div><div class="live-grid"><div class="live-current"><div class="live-current-head"><div><div class="live-pro-kicker">Now shooting · ${idx+1} of ${rows.length}</div><h2>${esc(current?.subject||'No requirement')}</h2><div class="live-variant">${esc(current?.variant||'')}</div></div>${it?`<span class="live-state ${liveStateClass(it.state)}">${liveStateText(it.state)}</span>`:''}</div>${current?.notes?`<div class="live-shot-notes"><strong>Brief note</strong><br>${esc(current.notes)}</div>`:''}${it?.note?`<div class="live-shot-notes"><strong>Live note</strong><br>${esc(it.note)}</div>`:''}<div class="live-capture-number"><b>${it?.captures||0}</b><span>captures logged for this requirement</span></div><div class="live-touch-controls"><button class="live-touch primary" id="liveCapture">+ Log Capture</button><button class="live-touch success" data-live-state="done">✓ Mark Done</button><button class="live-touch warn" data-live-state="reshoot">Needs Another</button><button class="live-touch ghost" data-live-state="skipped">Skip</button></div><div class="actions section"><button class="btn secondary" id="livePrev">← Previous</button><button class="btn secondary" id="liveNote">${icon('edit')}Add Note</button><button class="btn primary" id="liveNext">Next →</button></div></div><div class="grid" style="gap:16px"><div class="live-next-card"><label>Next</label><h3>${esc(next?.subject||'All done')}</h3><p>${esc(next?.variant||'Run the coverage check')}</p><div class="live-side-actions"><button class="btn primary" id="liveCheck">${icon('check')}Check Before Leaving</button><button class="btn secondary" id="liveFullscreen">Full Screen</button>${st.status==='complete'?`<button class="btn secondary" id="resumeLive">${icon('refresh')}Resume Live Shoot</button>`:''}</div></div><div class="live-queue-panel"><div class="live-queue-head"><h3>Shoot queue</h3><span class="pill purple">${sum.done}/${sum.total}</span></div><div class="live-queue">${rows.map((shot,n)=>{const x=liveItem(s,shot.id);return `<button class="live-queue-row ${shot.id===current?.id?'current':''}" data-live-shot="${esc(shot.id)}"><div><strong>${n+1}. ${esc(shot.subject)}</strong><small>${esc(shot.variant)}${x.note?' · note saved':''}</small></div><div class="live-queue-meta">${x.note?'<span class="live-note-dot"></span>':''}<span class="live-state ${liveStateClass(x.state)}">${liveStateText(x.state)}</span><span class="pill">${x.captures||0}</span></div></button>`}).join('')}</div></div></div></div></div>`;document.getElementById('liveCapture').onclick=()=>liveBumpCapture(s,current.id);document.querySelectorAll('[data-live-state]').forEach(b=>b.onclick=()=>liveMark(s,current.id,b.dataset.liveState));document.getElementById('livePrev').onclick=()=>liveMove(s,-1);document.getElementById('liveNext').onclick=()=>liveMove(s,1);document.getElementById('liveNote').onclick=()=>liveNoteModal(s,current.id);document.getElementById('liveCheck').onclick=()=>liveShootCheck(s);document.getElementById('liveFullscreen').onclick=liveFullscreen;document.querySelectorAll('[data-live-shot]').forEach(b=>b.onclick=()=>liveSetCurrent(s,b.dataset.liveShot));const r=document.getElementById('resumeLive');if(r)r.onclick=()=>resumeLiveShoot(s)}

'''
text = text.replace('function renderHistoryTab', js + 'function renderHistoryTab', 1)
text = text.replace("window.__HSM_TEST__={version:APP_VERSION,parseShotList,cleanName,coverage,makePreview,autoMatch,reviewSummary,hammingHash};", "window.__HSM_TEST__={version:APP_VERSION,parseShotList,cleanName,coverage,makePreview,autoMatch,reviewSummary,hammingHash,liveSummary,liveShootEntitled};", 1)

required = [
    "APP_VERSION='0.5.0'",
    "['live','Live Shoot Pro']",
    "function renderLiveShootTab",
    "function liveSummary",
    "function liveShootCheck",
    "function appendLiveShootOverview",
    "function appendLiveShootSettings",
    "live-shoot-preview",
    "Paid add-on",
]
for marker in required:
    assert marker in text, f'patch did not add: {marker}'

path.write_text(text)
print(f'Patched {path} with Live Shoot Pro')
